with p as (select id from liq_proveedores where nombre='JPMorgan Chase / Kinexys')
update liq_proveedores set email_patron=null, email_patron_fuente=' · confianza: baja',
 canales_publicos='[{"canal": "Sitio oficial Kinexys Digital Assets (con enlace ''Contact us'')", "valor": "https://www.jpmorgan.com/kinexys/digital-assets", "fuente": "https://www.jpmorgan.com/kinexys/digital-assets"}, {"canal": "Formulario ''Contact us'' de Kinexys (destino no capturado; página no accesible desde este entorno)", "valor": null, "fuente": "https://www.jpmorgan.com/kinexys/digital-assets"}, {"canal": "Newsroom J.P. Morgan Payments / Kinexys (comunicado de resultados Q1-2026, indexado y verificado)", "valor": "https://www.jpmorgan.com/payments/newsroom/payments-2026-q1-earnings", "fuente": "https://www.jpmorgan.com/payments/newsroom/payments-2026-q1-earnings"}, {"canal": "Contacto de prensa corporativo JPMorgan Chase (Joseph Evangelisti, tel. 212-270-7438; sin email publicado)", "valor": "212-270-7438", "fuente": "https://www.jpmorganchase.com/ir/news/2025/jpmc-investor-day-2025"}, {"canal": "LinkedIn página de empresa Kinexys by J.P. Morgan (handle no verificado)", "valor": null, "fuente": "https://www.jpmorgan.com/kinexys/digital-assets"}]'::jsonb, ruta_recomendada='1) Enviar el único correo a Kara Kennedy (Co-Head de Kinexys a cargo de Kinexys Digital Assets y Labs según bio PBW 2026; con base en Edimburgo) con CC a Keerthi Moudgal (Head of Product, Kinexys Digital Assets; cargo confirmado solo hasta 2025); al no existir email público ni patrón verificado, usar InMail de LinkedIn o el formulario ''Contact us'' de Kinexys Digital Assets solicitando el contacto directo. 2) Buscar intro cálida vía socios compartidos de Kinexys: Schroders (SOAR en Kinexys), Citco (Fund Flow), Chainlink (piloto Kinexys/Ondo 2025), Partior/DBS, Digital Asset (Canton) o Securitize/Apex si Kabal tiene relación. 3) Puente en español: Tomas Calatayud Guidi (argentino, Product Director de Kinexys Digital Payments, Nueva York) para una intro interna hacia Digital Assets. 4) Fallback: escalar a Oli Harris (Head of Kinexys desde abr-2026, confirmado por Bloomberg Government) por LinkedIn, o a Umar Farooq (Global Co-Head J.P. Morgan Payments, supervisa blockchain y pagos digitales; el ángulo Brasil/México no pudo corroborarse); usar prensa corporativa (212-270-7438) solo para confirmar el canal institucional correcto.',
 decisor=coalesce('Keerthi Moudgal — Head of Product, Kinexys Digital Assets',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Kinexys by J.P. Morgan (ex Onyx): depósitos tokenizados (JPMD), MMF tokenizados, Fund Flow, Tokenized Collateral Network.'||E'\n'||'Investigación automática 2026-10-18 (lote EXPLORE del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 12 búsquedas. Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='JPMorgan Chase / Kinexys'), v.* from (values
('Kara Kennedy','Co-Head de Kinexys by J.P. Morgan – Executive Director (a cargo de Kinexys Digital Assets y Kinexys Labs); el título ''Global Head of Market Development'' atribuido al comunicado de hitos 2026 no pudo corroborarse','Kinexys – Digital Assets / Labs','Edimburgo, Reino Unido (según eFinancialCareers, ene-2026)',null,null,'desconocido','entrada',1,'Co-dirige Kinexys con responsabilidad directa sobre Kinexys Digital Assets y Labs (tokenización, Fund Flow, TCN) y fue nombrada en ago-2025 para dirigir los proyectos de tokenización e investigación blockchain; es la persona natural para evaluar distribución secundaria, cross-listing y liquidez ancla, y es más accesible que el Head of Kinexys.','https://parisblockchainweek.com/speaker-2026/kara-kennedy','Verificación: sigue en Kinexys en 2026. La bio de speaker de Paris Blockchain Week 2026 la lista como Co-Head of Kinexys a cargo de los equipos Digital Assets y Labs; eFinancialCareers (ene-2026, https://www.efinancialcareers.com/news/jp-morgan-s-top-crypto-guy-in-singapore-is-leaving) la describe como executive director con base en Edimburgo (4,5 años en el banco, ingresó en 2021 desde BNY Mellon) y co-head restante tras la salida de Naveen Mallela. El título ''Global Head of Market Development'' solo aparece en el comunicado de hitos Kinexys 2026 citado originalmente (https://www.jpmorgan.com/payments/newsroom/kinexys-milestones-2026), que no pudo abrirse desde este entorno (dominio jpmorgan.com bloqueado por el proxy) y que ninguna búsqueda devolvió; es plausible que su título haya cambiado tras el nombramiento de Oli Harris (abr-2026) pero no está corroborado. Se corrige la ubicación (Edimburgo, no EE. UU.) y se sustituye la fuente por una indexada y verificable. Sin email público ni patrón corporativo corroborado.'),
('Oliver (Oli) Harris','Head of Kinexys by J.P. Morgan (nombrado en abril de 2026)','Kinexys (unidad blockchain / activos digitales)','Nueva York, EE. UU. (no confirmado)',null,null,'desconocido','decisor',2,'Nombrado en abr-2026 para dirigir Kinexys con mandato explícito de comercializar sus aplicaciones y profundizar la relación con clientes institucionales; ex Managing Director y Head of Digital Assets Americas en Goldman Sachs. Aprueba alianzas de la unidad.','https://news.bgov.com/crypto/jpmorgan-taps-former-goldman-exec-to-lead-blockchain-unit-1','Verificación: confirmado. Bloomberg Government (abr-2026) reporta que JPMorgan nombró a Oliver Harris, ex ejecutivo de Goldman Sachs, para liderar Kinexys; se incorporó ese mismo mes y sucede a Naveen Mallela, quien salió a Standard Chartered a inicios de 2026. Bloomberg Law (jun-2024) confirma su salida de Goldman como Head of Digital Assets Americas y MD. Un perfil de Paris Fintech Forum 2018 indica que antes lideró FinTech e In-Residence en el CIB de J.P. Morgan (misma persona, probable pero no confirmado explícitamente). Se reemplaza la fuente original (jpmorgan.com, no verificable desde este entorno) por la nota de Bloomberg Government indexada. Sin email público.'),
('Keerthi Moudgal','Head of Product, Kinexys Digital Assets','Kinexys Digital Assets (tokenización, Fund Flow, TCN)','Nueva York, EE. UU. (no confirmado)',null,null,'desconocido','dueno_programa',3,'Dirige el producto de la plataforma de tokenización multiactivo (Kinexys Digital Assets), base de Fund Flow, MMF tokenizados y Tokenized Collateral Network; interlocutora técnico-comercial para cross-listing de productos tokenizados.','https://consensus2025.coindesk.com/agenda/speaker/-keerthi-mougdal','Verificación: el título ''Head of Product, Kinexys Digital Assets'' está respaldado solo por bios de conferencias de 2025 (Consensus 2025 y Blockworks: https://blockworks.co/speaker/keerthi-moudgal); en el programa blockchain de J.P. Morgan desde 2018 y co-lanzó la plataforma en 2020. No se halló ninguna fuente fechada en 2026 que confirme que sigue en el cargo tras el cambio de liderazgo en Kinexys; tratar como probable pero no confirmado y validar en LinkedIn antes de contactar. Sin email público.'),
('Tomas Calatayud Guidi','Product Director (Executive Director), Kinexys Digital Payments','Kinexys Digital Payments (JPM Coin / JPMD, FX on-chain)','Nueva York, EE. UU. (según perfil; origen Argentina)',null,null,'desconocido','influencer',4,'Argentino, inició en J.P. Morgan Argentina (2014) y hoy dirige producto de pagos digitales en Kinexys; puede ser puente hispanohablante hacia el equipo de Digital Assets para liquidación de emisiones con depósitos tokenizados.','https://app.thebigwhale.io/people/tomas-calatayud-guidi','Verificación: el perfil de The Big Whale existe (indexado en versiones EN/FR/NL) y es consistente: Product Director / Executive Director – Kinexys desde feb-2025, trabajando en producto de Kinexys Digital Payments (pagos, blockchain, DLT y FX); en Kinexys desde ago-2022 como Product Manager VP; antes FX Product Management VP en EE. UU. (2021-2022); ingresó a J.P. Morgan Argentina en oct-2014 como FX Operations Analyst y se trasladó a Nueva York en sept-2018. Sigue siendo una única fuente agregadora sin bio oficial de J.P. Morgan; confirmar en LinkedIn antes de contactar. No tiene cobertura formal de LatAm; su área es producto de pagos, no tokenización de activos. Sin email público.'),
('Umar Farooq','Global Co-Head, J.P. Morgan Payments (ex CEO de Kinexys/Onyx; co-head junto a Max Neukirchen)','J.P. Morgan Payments (supervisa Kinexys y pagos digitales)','Nueva York, EE. UU. (no confirmado)',null,null,'desconocido','decisor',5,'Co-dirige Payments, unidad matriz de Kinexys, y sigue siendo responsable de las actividades de blockchain y pagos digitales del banco (Harvard Kennedy School, feb-2026); vía de escalamiento ejecutivo. El ángulo LatAm (Brasil/México como hubs de innovación) proviene de una nota de prensa que no pudo verificarse.','https://www.jpmorgan.com/payments/newsroom/payments-2026-q1-earnings','Verificación: confirmado como Global Co-Head of J.P. Morgan Payments en 2026, citado con ese título en el comunicado de resultados Q1-2026 de J.P. Morgan Payments (fuente actualizada) y en entrevistas de Bloomberg (abr-2026) y American Banker (may-2026); Harvard Kennedy School (feb-2026) lo describe como co-head de Global Payments y jefe de blockchain y pagos digitales. La nota ''brazil-mexico-payments-innovation'' citada originalmente no pudo abrirse desde este entorno ni apareció en búsquedas, por lo que la cobertura Brasil/México queda sin corroborar; se cambia el rol de ''cobertura_latam'' a ''decisor'' (escalamiento). Nivel demasiado alto para primer contacto. Sin email público.'),
('Kinexys Digital Assets – formulario ''Contact us''','Canal institucional genérico','Kinexys by J.P. Morgan','Global',null,null,'desconocido','canal_generico',5,'Único canal oficial publicado para consultas sobre la plataforma de tokenización; útil como fallback si no hay respuesta por LinkedIn.','https://www.jpmorgan.com/kinexys/digital-assets','Verificación: la página https://www.jpmorgan.com/kinexys/digital-assets no pudo abrirse desde este entorno (el proxy de salida rechaza jpmorgan.com), por lo que sigue sin confirmarse el destino del formulario ni un buzón de correo; se mantiene como canal oficial plausible. Prensa corporativa publica solo teléfono (212-270-7438), sin email.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
